#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.
# This wizard writes only epure.live-github.json, so the library's .env and
# GitHub-secret helpers are omitted.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  it from the start later.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# ask KEY "Prompt" reads a value into $KEY. Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" input s=$'\001' e=$'\002' p rc=0
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  printf -v "$key" '%s' "$input"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

_gh_ready() { command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; }

_file_mode() { stat -c %a "$1" 2>/dev/null || stat -f %Lp "$1"; }

# Reads only the first line, so the key body never reaches the terminal.
_is_private_key() {
  local first=""
  IFS= read -r first < "$1" || true
  [[ "$first" =~ ^-----BEGIN\ .*PRIVATE\ KEY----- ]]
}

run_wizard() {

TOTAL_STAGES=4

REPO_ROOT=$(git rev-parse --show-toplevel 2>/dev/null) || {
  warn "run this wizard from inside the EPURE checkout"; exit 1
}
CONFIG_FILE="${EPURE_LIVE_GITHUB_CONFIG:-$REPO_ROOT/epure.live-github.json}"

banner "EPURE live GitHub sandbox (npm run test:live:github)"

# ── Stage 1: sandbox repository ───────────────────────────────────────────
stage "Create the sandbox repository"
say "The live suite creates and deletes refs, branches and PRs under live/<run-id>/"
say "in a dedicated private repo. It needs a default branch with at least one commit."
ask SANDBOX_REPO "Sandbox repository (<owner>/<name>) [default: Giskard-AI/epure-live-sandbox]:" || true
[[ -z "${SANDBOX_REPO:-}" ]] && SANDBOX_REPO="Giskard-AI/epure-live-sandbox"
if [[ ! "$SANDBOX_REPO" =~ ^[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+$ ]]; then
  warn "invalid repository slug '${SANDBOX_REPO}'; expected <owner>/<name>"; exit 1
fi
SANDBOX_NAME_LOWER=$(printf '%s' "${SANDBOX_REPO#*/}" | tr '[:upper:]' '[:lower:]')
if [[ "$(printf '%s' "$SANDBOX_REPO" | tr '[:upper:]' '[:lower:]')" == "giskard-ai/epure" || "$SANDBOX_NAME_LOWER" != *sandbox* ]]; then
  warn "refusing '${SANDBOX_REPO}': the repository name must contain 'sandbox' (the live suite refuses anything else)"; exit 1
fi
SANDBOX_OWNER="${SANDBOX_REPO%%/*}"

if _gh_ready && gh repo view "$SANDBOX_REPO" >/dev/null 2>&1; then
  printf '  %s✓ exists%s %s\n' "$GREEN" "$RESET" "$SANDBOX_REPO"
  confirm "${SANDBOX_REPO} already exists. Is it disposable (nothing in it you need to keep)?" || {
    warn "pick a dedicated, disposable sandbox repository"; exit 1
  }
elif _gh_ready && confirm "Create private repo ${SANDBOX_REPO} with an initial README commit via gh?"; then
  gh repo create "$SANDBOX_REPO" --private --add-readme \
    --description "Disposable sandbox for EPURE live GitHub tests" >/dev/null
  printf '  %s✓ created%s %s\n' "$GREEN" "$RESET" "$SANDBOX_REPO"
else
  open_url "https://github.com/new"
  step "Owner: ${SANDBOX_OWNER}. Repository name: ${SANDBOX_REPO#*/}."
  step "Visibility: Private. Tick 'Add a README file'. Click 'Create repository'."
  note "If the repository already existed, make sure nothing in it needs to be kept."
  pause "Press Enter once ${SANDBOX_REPO} exists"
fi
pause "Press Enter to continue"

# ── Stage 2: test GitHub App ──────────────────────────────────────────────
stage "Create the test GitHub App"
OWNER_TYPE="User"
_gh_ready && OWNER_TYPE=$(gh api "users/${SANDBOX_OWNER}" --jq '.type' 2>/dev/null || echo "User")
if [[ "$OWNER_TYPE" == "Organization" ]]; then
  open_url "https://github.com/organizations/${SANDBOX_OWNER}/settings/apps/new"
else
  open_url "https://github.com/settings/apps/new"
fi
step "GitHub App name: $(printf '%s' "$SANDBOX_OWNER" | tr '[:upper:]' '[:lower:]')-epure-live-test (must be globally unique)."
step "Homepage URL: https://github.com/${SANDBOX_REPO}"
step "Webhook: untick 'Active'."
step "Repository permissions (nothing else):"
note "  - Contents: Read and write"
note "  - Pull requests: Read and write"
note "  - Metadata: Read-only (selected automatically)"
step "Where can this GitHub App be installed: 'Only on this account'. Click 'Create GitHub App'."
step "On the app's General page, copy the numeric App ID."
ask EPURE_LIVE_GITHUB_APP_ID "App ID:"
[[ "$EPURE_LIVE_GITHUB_APP_ID" =~ ^[0-9]+$ ]] || { warn "App ID must be numeric"; exit 1; }
step "Scroll to 'Private keys' and click 'Generate a private key'; a .pem file downloads."
note "Only the file path is stored in ${CONFIG_FILE}; the key itself is never printed."
ask KEY_SRC "Path to the downloaded .pem file:"
KEY_SRC="${KEY_SRC/#\~/$HOME}"
[[ -L "$KEY_SRC" ]] && { warn "refusing a symlink: ${KEY_SRC}"; exit 1; }
[[ -f "$KEY_SRC" ]] || { warn "no file at ${KEY_SRC}"; exit 1; }
_is_private_key "$KEY_SRC" || { warn "${KEY_SRC} does not start with a PEM private key header"; exit 1; }
KEY_PATH="$KEY_SRC"
KEY_DEST="$HOME/.config/epure/epure-live-sandbox.private-key.pem"
if [[ "$KEY_SRC" != "$KEY_DEST" ]] && confirm "Copy the key to ${KEY_DEST} (dir 0700, file 0600)?"; then
  if [[ -e "$KEY_DEST" ]] && ! confirm "${KEY_DEST} already exists. Overwrite it?"; then
    warn "kept the existing ${KEY_DEST}; re-run and choose another path"; exit 1
  fi
  install -d -m 700 "$(dirname "$KEY_DEST")"
  install -m 600 "$KEY_SRC" "$KEY_DEST"
  KEY_PATH="$KEY_DEST"
  if confirm "Delete the downloaded copy ${KEY_SRC}?"; then
    rm -f "$KEY_SRC"
  fi
fi
if [[ "$KEY_PATH" == /mnt/* ]]; then
  warn "refusing ${KEY_PATH}: chmod has no effect on Windows drives (drvfs); copy it into the Linux filesystem"; exit 1
fi
chmod 600 "$KEY_PATH"
KEY_MODE=$(_file_mode "$KEY_PATH")
[[ "$KEY_MODE" == "600" || "$KEY_MODE" == "400" ]] || {
  warn "key file mode is ${KEY_MODE}, expected 600"; exit 1
}
printf '  %s✓ key file%s %s (mode %s)\n' "$GREEN" "$RESET" "$KEY_PATH" "$KEY_MODE"
pause "Press Enter to continue"

# ── Stage 3: install the App on the sandbox only ──────────────────────────
stage "Install the App on ${SANDBOX_REPO}"
step "In the app's left sidebar click 'Install App', then 'Install' next to ${SANDBOX_OWNER}."
step "Choose 'Only select repositories' → ${SANDBOX_REPO} and confirm."
note "The live suite refuses to run if the installation reaches any other repository."
step "GitHub redirects to .../settings/installations/<number>; copy that number."
ask EPURE_LIVE_GITHUB_INSTALLATION_ID "Installation ID:"
[[ "$EPURE_LIVE_GITHUB_INSTALLATION_ID" =~ ^[0-9]+$ ]] || { warn "installation ID must be numeric"; exit 1; }
pause "Press Enter to continue"

# ── Stage 4: write the local config ───────────────────────────────────────
stage "Write ${CONFIG_FILE}"
if [[ "$KEY_PATH" == *[\"\\]* ]]; then
  warn "key path contains a quote or backslash; rename it and re-run"; exit 1
fi
if [[ -e "$CONFIG_FILE" ]] && ! confirm "${CONFIG_FILE} exists. Overwrite it?"; then
  SKIPPED+=("write ${CONFIG_FILE} (kept the existing file)")
else
  (umask 077 && printf '{\n  "repository": "%s",\n  "appId": "%s",\n  "privateKeyPath": "%s",\n  "installationId": %s\n}\n' \
    "$SANDBOX_REPO" "$EPURE_LIVE_GITHUB_APP_ID" "$KEY_PATH" "$EPURE_LIVE_GITHUB_INSTALLATION_ID" > "$CONFIG_FILE")
  chmod 600 "$CONFIG_FILE"
  printf '  %s✓ wrote%s %s (git-ignored, mode %s)\n' "$GREEN" "$RESET" "$CONFIG_FILE" "$(_file_mode "$CONFIG_FILE")"
fi
pause "Press Enter to finish"

finish
say "Run the live suite with:"
say "  npm run test:live:github"
printf '\n'
}

run_wizard "$@"; exit
